text:
{
  "claims": [
    {
      "anchor": "older versions of SQLite needed write access just to read a WAL-mode database",
      "claim_text": "Older versions of SQLite required write access to read a WAL-mode database.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 states write access was required to read a WAL-mode database."
    },
    {
      "anchor": "That restriction was lifted in version 3.22.0",
      "claim_text": "The write-access restriction for reading WAL-mode databases was relaxed beginning with SQLite version 3.22.0.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 4 says the constraint was relaxed beginning with 3.22.0."
    },
    {
      "anchor": "current versions can read a WAL database on read-only media as long as certain conditions are met",
      "claim_text": "Newer versions of SQLite can read a WAL-mode database on read-only media if one or more conditions are met.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 5 states this for newer versions."
    },
    {
      "anchor": "it is still good practice to switch to journal_mode=DELETE before burning a database image onto read-only media",
      "claim_text": "It is good practice to convert the database to PRAGMA journal_mode=DELETE before burning an SQLite database image onto read-only media.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 6 recommends this practice."
    },
    {
      "anchor": "before 3.11.0, rollback journal modes were likely to be faster for transactions over about 100 MB",
      "claim_text": "Before version 3.11.0, rollback journal modes were likely to be faster for transactions larger than about 100 megabytes.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S2", "rel": "entails"},
        {"sid": "P2.S5", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P2.S2 gives the 100MB threshold; P2.S5 says from 3.11.0 WAL is as efficient, implying before that it was not."
    },
    {
      "anchor": "from 3.11.0 on WAL handles large transactions as efficiently as rollback mode",
      "claim_text": "Beginning with version 3.11.0, WAL mode works as efficiently with large transactions as rollback mode.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S5", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 2 directly states this."
    },
    {
      "anchor": "Since version 3.7.4, a process can even use WAL without shared memory",
      "claim_text": "Beginning in SQLite version 3.7.4, WAL databases can be used without shared memory.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P8.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 8 states this capability began in 3.7.4."
    },
    {
      "anchor": "as long as it sets the locking mode to EXCLUSIVE before its first access",
      "claim_text": "A process can use WAL without shared memory if it sets locking_mode to EXCLUSIVE before the first attempted access.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P8.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 8 gives this condition."
    },
    {
      "anchor": "In WAL mode the file format version numbers in the database header are raised from 1 to 2",
      "claim_text": "In WAL mode, the database file format version numbers (bytes 18 and 19 in the database header) are increased from 1 to 2.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P9.S2", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 9 states this exactly."
    },
    {
      "anchor": "which is why SQLite versions older than 3.22.0 report \"file is encrypted or is not a database\" when they open such a file",
      "claim_text": "SQLite versions older than 3.22.0 report an error like \"file is encrypted or is not a database\" when opening a WAL-mode database.",
      "kind": "direct",
      "sure": false,
      "evidence": [
        {"sid": "P9.S2", "rel": "entails"},
        {"sid": "P9.S3", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Passage 9 says versions prior to 3.7.0, not 3.22.0, report this error; the claim's version threshold is wrong."
    },
    {
      "anchor": "The 3.22.0 release also made WAL the default journal mode for newly created databases",
      "claim_text": "SQLite version 3.22.0 made WAL the default journal mode for newly created databases.",
      "kind": "direct",
      "sure": false,
      "evidence": [],
      "check": null,
      "reasoning": "No passage states that 3.22.0 changed the default journal mode."
    }
  ]
}
